import redis, sys
SRC=dict(host='127.0.0.1',port=6379); DST=dict(host='127.0.0.1',port=6380)

def kv(lst):
    return {lst[i]:lst[i+1] for i in range(0,len(lst),2)} if isinstance(lst,list) else lst

def sid(b):
    a,c=b.split(b'-'); return (int(a),int(c))

def copy_stream(s,d,k):
    info=s.execute_command('XINFO','STREAM',k,'FULL','COUNT',0)
    info={ (x.decode() if isinstance(x,bytes) else x):v for x,v in info.items()}
    entries=info['entries']
    groups=[kv(g) for g in info['groups']]
    for g in groups: g[b'consumers']=[kv(c) for c in g[b'consumers']]
    existing={e[0] for e in entries}
    fakes=set()
    for g in groups:
        for p in g[b'pending']:
            if p[0] not in existing: fakes.add(p[0])
    allents=sorted([(sid(e[0]),e[0],e[1]) for e in entries]+[(sid(f),f,[b'_',b'_']) for f in fakes])
    d.execute_command('XGROUP','CREATE',k,'__tmp__','0','MKSTREAM')
    d.execute_command('XGROUP','DESTROY',k,'__tmp__')
    p=d.pipeline(transaction=False)
    for _,i,fields in allents: p.execute_command('XADD',k,i,*fields)
    p.execute()
    lastid=info['last-generated-id']; added=info['entries-added']+len(fakes); maxdel=info['max-deleted-entry-id']
    d.execute_command('XSETID',k,lastid,'ENTRIESADDED',max(added,len(allents)),'MAXDELETEDID',maxdel)
    for g in groups:
        args=['XGROUP','CREATE',k,g[b'name'],g[b'last-delivered-id']]
        if g[b'entries-read'] is not None: args+=['ENTRIESREAD',g[b'entries-read']]
        d.execute_command(*args)
        for c in g[b'consumers']:
            d.execute_command('XGROUP','CREATECONSUMER',k,g[b'name'],c[b'name'])
        for pid,cons,dtime,dcount in g[b'pending']:
            d.execute_command('XCLAIM',k,g[b'name'],cons,0,pid,'TIME',dtime,'RETRYCOUNT',dcount,'FORCE','JUSTID')
    if fakes:
        d.execute_command('XDEL',k,*fakes)
    d.execute_command('XSETID',k,lastid,'ENTRIESADDED',info['entries-added'],'MAXDELETEDID',maxdel)

def copy_key(s,d,k):
    t=s.type(k)
    if t==b'none': return
    if d.exists(k): d.delete(k)
    if t==b'string':
        d.set(k,s.get(k))
    elif t==b'list':
        v=s.lrange(k,0,-1)
        for i in range(0,len(v),1000): d.rpush(k,*v[i:i+1000])
    elif t==b'set':
        v=list(s.smembers(k))
        for i in range(0,len(v),1000): d.sadd(k,*v[i:i+1000])
    elif t==b'zset':
        raw=s.execute_command('ZRANGE',k,0,-1,'WITHSCORES',NEVER_DECODE=True)
        # raw is flat list member,score(as bytes)
        args=[]
        for i in range(0,len(raw),2): args+= [raw[i+1],raw[i]]
        for i in range(0,len(args),2000): d.execute_command('ZADD',k,*args[i:i+2000])
    elif t==b'hash':
        h=s.hgetall(k)
        flat=[x for kvp in h.items() for x in kvp]
        for i in range(0,len(flat),2000): d.execute_command('HSET',k,*flat[i:i+2000])
        fields=list(h.keys())
        if fields:
            ets=s.execute_command('HPEXPIRETIME',k,'FIELDS',len(fields),*fields)
            for f,e in zip(fields,ets):
                if e>0: d.execute_command('HPEXPIREAT',k,e,'FIELDS',1,f)
    elif t==b'stream':
        copy_stream(s,d,k)
    else:
        raise Exception('unsupported type %r for %r'%(t,k))
    et=s.execute_command('PEXPIRETIME',k)
    if et>0: d.execute_command('PEXPIREAT',k,et)

def main():
    s0=redis.Redis(**SRC)
    dbs=[int(x[2:]) for x in s0.info('keyspace').keys()]
    for db in dbs:
        s=redis.Redis(db=db,**SRC); d=redis.Redis(db=db,**DST)
        n=0
        for k in s.scan_iter(count=1000):
            copy_key(s,d,k); n+=1
        print('db',db,'copied',n)
main()
